"""Aim one measured displacement ahead of the moving boss.

Live g1288 2026-11-20: the boss measured (938,461) then (762,629) ten minutes
later, while a march from the waypoint takes about six minutes. Chasing the
last cell lets it walk away; the pursuit now offsets its destination by one
measured displacement, clamped so the lead cell stays near the island.
"""
from types import SimpleNamespace

from docich.hanjuku_speedrun import hanjuku_chart as chart
from docich.hanjuku_speedrun.hanjuku.flows import boss_pursuit as bp
from docich.hanjuku_speedrun.hanjuku.os_layer import navigation as nav


def memory(**extra):
    mem = {
        'chapter': 9,
        'tick': 10000,
        'world': {'sorties': {}, 'garrison': {}},
        bp.LIST_KEY: {'ミント': {'step': 'A', 'launched': 9500}},
        'boss_cell': {'chapter': 9, 'cell': [810, 645], 'tick': 9990, 'readings': 2},
        'plan': {'active': None},
    }
    mem.update(extra)
    return mem


def test_the_lead_extrapolates_one_measurement_and_clamps():
    probe = {'boss_cell0': {'cell': [1000, 1000], 'tick': 100}}
    mem = memory(boss_cell={'cell': [1100, 940], 'tick': 200})
    assert bp._lead(mem, probe) == (150, -90)


def test_a_small_or_stale_displacement_is_not_used():
    probe = {'boss_cell0': {'cell': [1000, 1000], 'tick': 100}}
    assert bp._lead(memory(boss_cell={'cell': [1004, 1002], 'tick': 200}), probe) is None
    assert bp._lead(memory(boss_cell={'cell': [1200, 900], 'tick': 100}), probe) is None
    assert bp._lead(memory(boss_cell={'cell': [1200, 900], 'tick': 9999}), probe) is None


def test_the_pursuit_step_applies_the_lead_to_its_aim_cell():
    chart.set_boss_cell(9, (800, 600))
    try:
        mem = memory(pursuit_lead=[100, -50])
        assert nav.boss_probe_cell(mem, 'ボス', 'PURSUIT') == (900, 550)
        # a castle order keeps the documented first-leg waypoint
        assert nav.boss_probe_cell(mem, 'ボス', 'A') == chart.CH9_BOSS_WAYPOINT
    finally:
        chart.set_boss_cell(9, None)


